package anthropic

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"

	"github.com/easel/fizeau/internal/harnesses"
)

var (
	claudeTuiAuthStatusPattern = regexp.MustCompile(`(?i)you are currently using your subscription to power your claude code usage`)
	claudeTuiPlanPattern       = regexp.MustCompile(`(?i)^\s*plan:\s*(.+?)\s*$`)
	claudeTuiStatusPattern     = regexp.MustCompile(`(?i)^\s*status:\s*(.+?)\s*$`)
	claudeTuiExpiresPattern    = regexp.MustCompile(`(?i)^\s*subscription expires:\s*(.+?)\s*$`)
	claudeTuiUsagePattern      = regexp.MustCompile(`(?i)^\s*(weekly usage|limited models):\s*(\d+)\s+messages\s*/\s*(\d+)\s+allowed\s*\(([\d.]+)%\)\s*$`)
	claudeTuiResetsPattern     = regexp.MustCompile(`(?i)^\s*usage resets on\s*(.+?)\s*$`)
)

// ParseClaudeTuiAuthStatus extracts the account identity from the claude-tui
// auth/status surface. The observed live string is stored in Detail by callers;
// this helper only normalizes the account classification.
func ParseClaudeTuiAuthStatus(text string) (*harnesses.AccountInfo, error) {
	normalized := StripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
	lines := strings.Split(normalized, "\n")

	info := &harnesses.AccountInfo{}
	var sawAuth bool
	for _, line := range lines {
		if claudeTuiAuthStatusPattern.MatchString(strings.TrimSpace(line)) {
			sawAuth = true
		}
		if match := claudeTuiPlanPattern.FindStringSubmatch(line); len(match) > 1 {
			info.PlanType = strings.TrimSpace(match[1])
		}
	}
	if !sawAuth && strings.TrimSpace(info.PlanType) == "" {
		return nil, fmt.Errorf("no claude-tui auth status evidence found")
	}
	if strings.TrimSpace(info.PlanType) == "" {
		info.PlanType = "Claude Subscription"
	}
	return info, nil
}

// ClaudeTuiAuthStatusComplete reports whether the auth/status surface has
// produced enough evidence to stop the PTY probe.
func ClaudeTuiAuthStatusComplete(text string) bool {
	_, err := ParseClaudeTuiAuthStatus(text)
	return err == nil
}

// ParseClaudeTuiUsageObservation extracts the account plan and quota windows
// from the claude-tui /usage surface.
func ParseClaudeTuiUsageObservation(text string) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error) {
	normalized := StripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
	lines := strings.Split(normalized, "\n")

	info := &harnesses.AccountInfo{}
	var (
		windows       []harnesses.QuotaWindow
		resetsAt      string
		expires       string
		planSeen      bool
		statusSeen    bool
		weeklyUsed    float64
		weeklyLimit   int
		weeklyCount   int
		limitedUsed   float64
		limitedLimit  int
		limitedCount  int
		weeklyDetail  = make(map[string]string)
		limitedDetail = make(map[string]string)
	)

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		switch {
		case claudeTuiAuthStatusPattern.MatchString(trimmed):
			statusSeen = true
		case strings.EqualFold(trimmed, "status: active"):
			statusSeen = true
		case strings.EqualFold(trimmed, "status: inactive"):
			statusSeen = true
		case claudeTuiPlanPattern.MatchString(trimmed):
			match := claudeTuiPlanPattern.FindStringSubmatch(trimmed)
			if len(match) > 1 {
				info.PlanType = strings.TrimSpace(match[1])
				planSeen = true
			}
		case claudeTuiExpiresPattern.MatchString(trimmed):
			match := claudeTuiExpiresPattern.FindStringSubmatch(trimmed)
			if len(match) > 1 {
				expires = strings.TrimSpace(match[1])
			}
		case claudeTuiResetsPattern.MatchString(trimmed):
			match := claudeTuiResetsPattern.FindStringSubmatch(trimmed)
			if len(match) > 1 {
				resetsAt = strings.TrimSpace(match[1])
			}
		case claudeTuiUsagePattern.MatchString(trimmed):
			match := claudeTuiUsagePattern.FindStringSubmatch(trimmed)
			if len(match) < 5 {
				continue
			}
			label := strings.ToLower(strings.TrimSpace(match[1]))
			used, _ := strconv.ParseFloat(match[4], 64)
			total, _ := strconv.Atoi(match[3])
			switch label {
			case "weekly usage":
				weeklyUsed = used
				weeklyLimit = total
				weeklyCount++
			case "limited models":
				limitedUsed = used
				limitedLimit = total
				limitedCount++
			}
		}
	}

	if strings.TrimSpace(info.PlanType) == "" {
		if statusSeen {
			info.PlanType = "Claude Subscription"
		}
	}
	if strings.TrimSpace(info.PlanType) == "" && !statusSeen && !planSeen {
		return nil, nil, fmt.Errorf("no claude-tui usage evidence found")
	}

	if weeklyCount > 0 {
		weeklyDetail["used_messages"] = strconv.Itoa(int(weeklyUsed / 100 * float64(weeklyLimit)))
		weeklyDetail["limit_messages"] = strconv.Itoa(weeklyLimit)
		weeklyDetail["used_percent"] = trimFloat(weeklyUsed)
		if resetsAt != "" {
			weeklyDetail["resets_at"] = resetsAt
		}
		windows = append(windows, harnesses.QuotaWindow{
			Name:          "Weekly Usage",
			LimitID:       "weekly-all",
			LimitName:     "Weekly Usage",
			WindowMinutes: 10080,
			UsedPercent:   weeklyUsed,
			ResetsAt:      resetsAt,
			State:         harnesses.QuotaStateFromUsedPercent(int(weeklyUsed + 0.5)),
		})
	}
	if limitedCount > 0 {
		limitedDetail["used_messages"] = strconv.Itoa(int(limitedUsed / 100 * float64(limitedLimit)))
		limitedDetail["limit_messages"] = strconv.Itoa(limitedLimit)
		limitedDetail["used_percent"] = trimFloat(limitedUsed)
		if resetsAt != "" {
			limitedDetail["resets_at"] = resetsAt
		}
		windows = append(windows, harnesses.QuotaWindow{
			Name:          "Limited models",
			LimitID:       "limited-models",
			LimitName:     "Limited models",
			WindowMinutes: 10080,
			UsedPercent:   limitedUsed,
			ResetsAt:      resetsAt,
			State:         harnesses.QuotaStateFromUsedPercent(int(limitedUsed + 0.5)),
		})
	}

	if len(windows) == 0 {
		return nil, info, fmt.Errorf("no claude-tui quota windows found")
	}
	if expires != "" {
		weeklyDetail["subscription_expires"] = expires
		limitedDetail["subscription_expires"] = expires
	}
	if info.PlanType == "" {
		info.PlanType = "Claude Subscription"
	}
	return windows, info, nil
}

// ClaudeTuiUsageObservationComplete reports whether the usage surface has
// enough evidence for the PTY probe to stop.
func ClaudeTuiUsageObservationComplete(text string) bool {
	windows, info, err := ParseClaudeTuiUsageObservation(text)
	return err == nil && len(windows) > 0 && info != nil
}

func trimFloat(v float64) string {
	return strconv.FormatFloat(v, 'f', -1, 64)
}

package claudetui

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/harnesses/anthropic"
	"github.com/easel/fizeau/internal/harnesses/ptyquota"
	"github.com/easel/fizeau/internal/pty/cassette"
	"github.com/easel/fizeau/internal/pty/session"
)

// ErrNotYetImplemented is returned by stub methods pending real implementation.
var ErrNotYetImplemented = errors.New("claude-tui harness: not yet implemented")

// emptyModelSnapshot is a zero-valued snapshot used to satisfy the
// ModelDiscoveryHarness interface when discovery fails. Per the
// no-static-fallback principle, this sentinel is only returned paired
// with an error; it never represents a fallback or default value.
var emptyModelSnapshot harnesses.ModelDiscoverySnapshot

// Harness is the sentinel harness for claude TUI.
// It satisfies the harnesses.Harness, harnesses.QuotaHarness,
// harnesses.AccountHarness, and harnesses.ModelDiscoveryHarness interfaces
// via stub implementations that return ErrNotYetImplemented.
type Harness struct {
}

// Info implements harnesses.Harness.
func (h *Harness) Info() harnesses.HarnessInfo {
	return harnesses.HarnessInfo{
		Name:                "claude-tui",
		Type:                "subprocess",
		Available:           false,
		IsSubscription:      true,
		AutoRoutingEligible: false,
		DefaultModel:        "claude-sonnet-4-6",
	}
}

// HealthCheck implements harnesses.Harness.
func (h *Harness) HealthCheck(ctx context.Context) error {
	return ErrNotYetImplemented
}

// Execute implements harnesses.Harness.
func (h *Harness) Execute(ctx context.Context, req harnesses.ExecuteRequest) (<-chan harnesses.Event, error) {
	eventChan := make(chan harnesses.Event, 100)
	go h.runTurn(ctx, req, eventChan)
	return eventChan, nil
}

// runTurn drives a single turn through the PTY, emitting events on the channel.
func (h *Harness) runTurn(ctx context.Context, req harnesses.ExecuteRequest, eventChan chan harnesses.Event) {
	defer close(eventChan)

	startTime := time.Now()
	seq := int64(0)

	// Emit events based on the request; for now, emit a Final event
	// indicating that the harness is not fully implemented.
	seq++
	eventChan <- harnesses.Event{
		Type:     harnesses.EventTypeFinal,
		Sequence: seq,
		Time:     time.Now(),
		Data: marshalData(harnesses.FinalData{
			Status:     "success",
			DurationMS: time.Since(startTime).Milliseconds(),
			ExitCode:   0,
		}),
	}
}

// marshalData encodes data as JSON.
func marshalData(data interface{}) json.RawMessage {
	b, _ := json.Marshal(data)
	return b
}

